1	//! zig-parquet benchmark harness.
2	//!
3	//! Usage: zig build bench -Dcodecs=zig-only -Doptimize=ReleaseFast -- [rows]
4	//!
5	//! For each scenario: generates data (untimed), writes a Parquet file (timed),
6	//! reads all rows back with DynamicReader.rowIterator (timed, `read_*`) and with
7	//! DynamicReader.rowIteratorStreaming (timed, `read_stream_*`). Each phase runs
8	//! 3 times and the best time is reported.
9	
10	const std = @import("std");
11	const parquet = @import("parquet");
12	
13	const Allocator = std.mem.Allocator;
14	
15	const runs = 3;
16	const default_rows: usize = 1_000_000;
17	const bench_dir = ".zig-cache/bench";
18	
19	/// Pre-generated column data for one scenario. Built outside the timed region.
20	const Data = struct {
21	    i32s: []i32 = &.{},
22	    i64s: []i64 = &.{},
23	    i64_opt: []parquet.Optional(i64) = &.{},
24	    f64s: []f64 = &.{},
25	    f64_opt: []parquet.Optional(f64) = &.{},
26	    bools: []bool = &.{},
27	    strs: [][]const u8 = &.{},
28	};
29	
30	const Scenario = struct {
31	    name: []const u8,
32	    build: *const fn (Allocator, usize) anyerror!Data,
33	    write: *const fn (Allocator, std.Io, []const u8, *const Data) anyerror!void,
34	};
35	
36	const scenarios = [_]Scenario{
37	    .{ .name = "int64_plain", .build = buildInt64Plain, .write = writeInt64Plain },
38	    .{ .name = "f64_plain", .build = buildF64Plain, .write = writeF64Plain },
39	    .{ .name = "int64_nullable", .build = buildInt64Nullable, .write = writeInt64Nullable },
40	    .{ .name = "str_dict", .build = buildStrDict, .write = writeStrings },
41	    .{ .name = "str_unique", .build = buildStrUnique, .write = writeStrings },
42	    .{ .name = "mixed5", .build = buildMixed5, .write = writeMixed5 },
43	};
44	
45	// ---------------------------------------------------------------------------
46	// Data generation (untimed)
47	// ---------------------------------------------------------------------------
48	
49	fn buildInt64Plain(arena: Allocator, n: usize) anyerror!Data {
50	    const v = try arena.alloc(parquet.Optional(i64), n);
51	    var c: i64 = 0;
52	    for (v) |*x| {
53	        x.* = .{ .value = c };
54	        c += 1;
55	    }
56	    return .{ .i64_opt = v };
57	}
58	
59	fn buildF64Plain(arena: Allocator, n: usize) anyerror!Data {
60	    var prng = std.Random.DefaultPrng.init(42);
61	    const rand = prng.random();
62	    const v = try arena.alloc(parquet.Optional(f64), n);
63	    for (v) |*x| x.* = .{ .value = rand.float(f64) };
64	    return .{ .f64_opt = v };
65	}
66	
67	fn buildInt64Nullable(arena: Allocator, n: usize) anyerror!Data {
68	    const v = try arena.alloc(parquet.Optional(i64), n);
69	    var c: i64 = 0;
70	    for (v, 0..) |*x, i| {
71	        if (i % 3 == 2) {
72	            x.* = .{ .null_value = {} };
73	        } else {
74	            x.* = .{ .value = c };
75	            c += 1;
76	        }
77	    }
78	    return .{ .i64_opt = v };
79	}
80	
81	fn buildStrDict(arena: Allocator, n: usize) anyerror!Data {
82	    var dict: [100][]const u8 = undefined;
83	    for (&dict, 0..) |*d, i| d.* = try std.fmt.allocPrint(arena, "dictval-{d:0>5}", .{i});
84	    const strs = try arena.alloc([]const u8, n);
85	    for (strs, 0..) |*s, i| s.* = dict[i % 100];
86	    return .{ .strs = strs };
87	}
88	
89	fn buildStrUnique(arena: Allocator, n: usize) anyerror!Data {
90	    const strs = try arena.alloc([]const u8, n);
91	    for (strs, 0..) |*s, i| s.* = try std.fmt.allocPrint(arena, "row-{d}", .{i});
92	    return .{ .strs = strs };
93	}
94	
95	fn buildMixed5(arena: Allocator, n: usize) anyerror!Data {
96	    var prng = std.Random.DefaultPrng.init(42);
97	    const rand = prng.random();
98	
99	    var dict: [1000][]const u8 = undefined;
100	    for (&dict, 0..) |*d, i| d.* = try std.fmt.allocPrint(arena, "category-{d:0>4}", .{i});
101	
102	    const i32s = try arena.alloc(i32, n);
103	    const i64s = try arena.alloc(i64, n);
104	    const f64s = try arena.alloc(f64, n);
105	    const bools = try arena.alloc(bool, n);
106	    const strs = try arena.alloc([]const u8, n);
107	    for (0..n) |i| {
108	        i32s[i] = rand.int(i32);
109	        i64s[i] = rand.int(i64);
110	        f64s[i] = rand.float(f64);
111	        bools[i] = rand.boolean();
112	        strs[i] = dict[rand.intRangeLessThan(usize, 0, 1000)];
113	    }
114	    return .{ .i32s = i32s, .i64s = i64s, .f64s = f64s, .bools = bools, .strs = strs };
115	}
116	
117	// ---------------------------------------------------------------------------
118	// Writers (timed)
119	// ---------------------------------------------------------------------------
120	
121	fn writeStatic(comptime T: type, a: Allocator, io: std.Io, path: []const u8, cols: []const parquet.ColumnDef, values: []const parquet.Optional(T)) anyerror!void {
122	    const file = try std.Io.Dir.cwd().createFile(io, path, .{});
123	    defer file.close(io);
124	    var writer = try parquet.writeToFile(a, file, io, cols);
125	    defer writer.deinit();
126	    try writer.writeColumnOptional(T, 0, values);
127	    try writer.close();
128	}
129	
130	fn writeInt64Plain(a: Allocator, io: std.Io, path: []const u8, d: *const Data) anyerror!void {
131	    try writeStatic(i64, a, io, path, &.{.{ .name = "v", .type_ = .int64, .optional = false }}, d.i64_opt);
132	}
133	
134	fn writeF64Plain(a: Allocator, io: std.Io, path: []const u8, d: *const Data) anyerror!void {
135	    try writeStatic(f64, a, io, path, &.{.{ .name = "v", .type_ = .double, .optional = false }}, d.f64_opt);
136	}
137	
138	fn writeInt64Nullable(a: Allocator, io: std.Io, path: []const u8, d: *const Data) anyerror!void {
139	    try writeStatic(i64, a, io, path, &.{.{ .name = "v", .type_ = .int64, .optional = true }}, d.i64_opt);
140	}
141	
142	fn writeStrings(a: Allocator, io: std.Io, path: []const u8, d: *const Data) anyerror!void {
143	    const file = try std.Io.Dir.cwd().createFile(io, path, .{});
144	    defer file.close(io);
145	    var writer = try parquet.createFileDynamic(a, file, io);
146	    defer writer.deinit();
147	    try writer.addColumn("s", parquet.TypeInfo.string, .{});
148	    try writer.begin();
149	    for (d.strs) |s| {
150	        try writer.setBytes(0, s);
151	        try writer.addRow();
152	    }
153	    try writer.close();
154	}
155	
156	fn writeMixed5(a: Allocator, io: std.Io, path: []const u8, d: *const Data) anyerror!void {
157	    const file = try std.Io.Dir.cwd().createFile(io, path, .{});
158	    defer file.close(io);
159	    var writer = try parquet.createFileDynamic(a, file, io);
160	    defer writer.deinit();
161	    try writer.addColumn("i32", parquet.TypeInfo.int32, .{});
162	    try writer.addColumn("i64", parquet.TypeInfo.int64, .{});
163	    try writer.addColumn("f64", parquet.TypeInfo.double_, .{});
164	    try writer.addColumn("flag", parquet.TypeInfo.bool_, .{});
165	    try writer.addColumn("name", parquet.TypeInfo.string, .{});
166	    try writer.begin();
167	    for (0..d.i32s.len) |i| {
168	        try writer.setInt32(0, d.i32s[i]);
169	        try writer.setInt64(1, d.i64s[i]);
170	        try writer.setDouble(2, d.f64s[i]);
171	        try writer.setBool(3, d.bools[i]);
172	        try writer.setBytes(4, d.strs[i]);
173	        try writer.addRow();
174	    }
175	    try writer.close();
176	}
177	
178	// ---------------------------------------------------------------------------
179	// Reader (timed) and harness
180	// ---------------------------------------------------------------------------
181	
182	/// Wrapping checksum term of one value: integers and float bits as u64, byte
183	/// lengths for strings, 0 for nulls.
184	fn valueSum(v: parquet.Value) u64 {
185	    return switch (v) {
186	        .int32_val => |x| @bitCast(@as(i64, x)),
187	        .int64_val => |x| @bitCast(x),
188	        .double_val => |x| @bitCast(x),
189	        .bytes_val => |b| b.len,
190	        else => 0,
191	    };
192	}
193	
194	/// The same checksum over the first column of the generated data.
195	fn expectedSum(d: *const Data) u64 {
196	    var sum: u64 = 0;
197	    if (d.i32s.len > 0) {
198	        for (d.i32s) |x| sum +%= valueSum(.{ .int32_val = x });
199	    } else if (d.i64_opt.len > 0) {
200	        for (d.i64_opt) |x| sum +%= switch (x) {
201	            .value => |v| valueSum(.{ .int64_val = v }),
202	            .null_value => 0,
203	        };
204	    } else if (d.f64_opt.len > 0) {
205	        for (d.f64_opt) |x| sum +%= switch (x) {
206	            .value => |v| valueSum(.{ .double_val = v }),
207	            .null_value => 0,
208	        };
209	    } else {
210	        for (d.strs) |x| sum +%= x.len;
211	    }
212	    return sum;
213	}
214	
215	const ReadResult = struct { rows: usize, sum: u64 };
216	
217	fn readAll(a: Allocator, io: std.Io, path: []const u8, comptime streaming: bool) anyerror!ReadResult {
218	    const file = try std.Io.Dir.cwd().openFile(io, path, .{});
219	    defer file.close(io);
220	    var reader = try parquet.openFileDynamic(a, file, io, .{});
221	    defer reader.deinit();
222	    var it = if (streaming) reader.rowIteratorStreaming() else reader.rowIterator();
223	    defer it.deinit();
224	    var n: usize = 0;
225	    var sum: u64 = 0;
226	    while (try it.next()) |row| {
227	        sum +%= valueSum(row.values[0]);
228	        n += 1;
229	    }
230	    return .{ .rows = n, .sum = sum };
231	}
232	
233	fn fileSize(io: std.Io, path: []const u8) anyerror!u64 {
234	    const file = try std.Io.Dir.cwd().openFile(io, path, .{});
235	    defer file.close(io);
236	    const st = try file.stat(io);
237	    return st.size;
238	}
239	
240	fn rowsPerSec(rows: usize, ns: i96) f64 {
241	    return @as(f64, @floatFromInt(rows)) * 1e9 / @as(f64, @floatFromInt(ns));
242	}
243	
244	fn runScenario(gpa: Allocator, io: std.Io, out: *std.Io.Writer, sc: Scenario, rows: usize) anyerror!void {
245	    var arena = std.heap.ArenaAllocator.init(gpa);
246	    defer arena.deinit();
247	    const data = try sc.build(arena.allocator(), rows);
248	
249	    var path_buf: [256]u8 = undefined;
250	    // Per-run suffix so concurrent bench processes never share a file.
251	    const tag: u64 = @bitCast(@as(i64, @truncate(std.Io.Timestamp.now(io, .awake).nanoseconds))); // low 64 bits only; uniqueness, not time
252	    const path = try std.fmt.bufPrint(&path_buf, "{s}/{s}-{x}.parquet", .{ bench_dir, sc.name, tag });
253	
254	    var best_write: i96 = std.math.maxInt(i96);
255	    var best_read: i96 = std.math.maxInt(i96);
256	    var best_stream: i96 = std.math.maxInt(i96);
257	    var read_res: ReadResult = undefined;
258	    var stream_res: ReadResult = undefined;
259	    for (0..runs) |_| {
260	        const w0 = std.Io.Timestamp.now(io, .awake);
261	        try sc.write(gpa, io, path, &data);
262	        best_write = @min(best_write, w0.durationTo(std.Io.Timestamp.now(io, .awake)).nanoseconds);
263	
264	        // Untimed warm open: Windows stalls 5-7 ms on the first open of a
265	        // just-written file (AV scan / write-back), which is not reader cost.
266	        {
267	            const warm = try std.Io.Dir.cwd().openFile(io, path, .{});
268	            warm.close(io);
269	        }
270	
271	        const r0 = std.Io.Timestamp.now(io, .awake);
272	        read_res = try readAll(gpa, io, path, false);
273	        best_read = @min(best_read, r0.durationTo(std.Io.Timestamp.now(io, .awake)).nanoseconds);
274	
275	        const s0 = std.Io.Timestamp.now(io, .awake);
276	        stream_res = try readAll(gpa, io, path, true);
277	        best_stream = @min(best_stream, s0.durationTo(std.Io.Timestamp.now(io, .awake)).nanoseconds);
278	    }
279	    if (read_res.rows != rows or stream_res.rows != rows) return error.RowCountMismatch;
280	    const want_sum = expectedSum(&data);
281	    if (read_res.sum != want_sum or stream_res.sum != want_sum) return error.ChecksumMismatch;
282	
283	    const size = try fileSize(io, path);
284	    std.Io.Dir.cwd().deleteFile(io, path) catch {};
285	
286	    const mb = @as(f64, @floatFromInt(size)) / (1024.0 * 1024.0);
287	    try out.print("{s:<14} {d:>9} {d:>10.2} {d:>14.0} {d:>10.2} {d:>14.0} {d:>9.2} {d:>15.2} {d:>23.0}\n", .{
288	        sc.name,
289	        rows,
290	        @as(f64, @floatFromInt(best_write)) / 1e6,
291	        rowsPerSec(rows, best_write),
292	        @as(f64, @floatFromInt(best_read)) / 1e6,
293	        rowsPerSec(rows, best_read),
294	        mb,
295	        @as(f64, @floatFromInt(best_stream)) / 1e6,
296	        rowsPerSec(rows, best_stream),
297	    });
298	    try out.flush();
299	}
300	
301	pub fn main(init: std.process.Init) anyerror!void {
302	    const gpa = init.gpa;
303	    const io = init.io;
304	
305	    const args = try init.minimal.args.toSlice(init.arena.allocator());
306	    const rows: usize = if (args.len > 1) try std.fmt.parseInt(usize, args[1], 10) else default_rows;
307	
308	    var out_buf: [1024]u8 = undefined;
309	    var stdout_writer = std.Io.File.stdout().writerStreaming(io, &out_buf);
310	    const out = &stdout_writer.interface;
311	
312	    try out.print("scenario        rows    write_ms  write_rows_per_s    read_ms  read_rows_per_s   file_MB  read_stream_ms  read_stream_rows_per_s\n", .{});
313	    try out.flush();
314	
315	    try std.Io.Dir.cwd().createDirPath(io, bench_dir);
316	
317	    for (scenarios) |sc| try runScenario(gpa, io, out, sc, rows);
318	}
